   447  KArchiveDirectory *KArchive::findOrCreate(const QString &path)
   448  {
   449      //qCDebug(KArchiveLog) << path;
   450      if (path.isEmpty() || path == QLatin1String("/") || path == QLatin1String(".")) { // root dir => found
   451          //qCDebug(KArchiveLog) << "returning rootdir";
   452          return rootDir();
   453      }
   454      // Important note : for tar files containing absolute paths
   455      // (i.e. beginning with "/"), this means the leading "/" will
   456      // be removed (no KDirectory for it), which is exactly the way
   457      // the "tar" program works (though it displays a warning about it)
   458      // See also KArchiveDirectory::entry().
   459
   460      // Already created ? => found
   461      const KArchiveEntry *ent = rootDir()->entry(path);
   462      if (ent) {
   463          if (ent->isDirectory())
   464              //qCDebug(KArchiveLog) << "found it";
   465          {
   466              const KArchiveDirectory *dir = static_cast<const KArchiveDirectory *>(ent);
   467              return const_cast<KArchiveDirectory *>(dir);
   468          } else {
   469              const KArchiveFile *file = static_cast<const KArchiveFile *>(ent);
   470              if (file->size() > 0) {
   471                  qCWarning(KArchiveLog) << path << "is normal file, but there are file paths in the archive assuming it is a directory, bailing out";
   472                  return nullptr;
   473              }
   474
   475              qCDebug(KArchiveLog) << path << " is an empty file, assuming it is actually a directory and replacing";
   476              KArchiveEntry *myEntry = const_cast<KArchiveEntry*>(ent);
   477              rootDir()->removeEntry(myEntry);
   478              delete myEntry;
   479          }
   480      }
   481
   482      // Otherwise go up and try again
   483      int pos = path.lastIndexOf(QLatin1Char('/'));
   484      KArchiveDirectory *parent;
   485      QString dirname;
   486      if (pos == -1) { // no more slash => create in root dir
   487          parent =  rootDir();
   488          dirname = path;
   489      } else {
   490          QString left = path.left(pos);
   491          dirname = path.mid(pos + 1);
   492          parent = findOrCreate(left);   // recursive call... until we find an existing dir.
   493      }
   494
   495      //qCDebug(KArchiveLog) << "found parent " << parent->name() << " adding " << dirname << " to ensure " << path;
   496      // Found -> add the missing piece
   497      KArchiveDirectory *e = new KArchiveDirectory(this, dirname, d->rootDir->permissions(),
   498                                                   d->rootDir->date(), d->rootDir->user(),
   499                                                   d->rootDir->group(), QString());
   500      parent->addEntry(e);
   501      return e; // now a directory to <path> exists
   502  }
